export interface CheckoutPayload {
  orderId: string;
  userId: string;
  items: Array<{ sku: string; qty: number }>;
}

export async function processCheckout(
  payload: CheckoutPayload,
  inventorySvc: { reserve: (id: string, items: any[]) => Promise<void>; release: (id: string) => Promise<void> },
  paymentSvc: { charge: (id: string, user: string) => Promise<void> },
  loyaltySvc: { deductPoints: (user: string, pts: number) => Promise<void> }
): Promise<void> {

  // continue running to completion without cancellation or rollback compensation.
  await Promise.all([
    inventorySvc.reserve(payload.orderId, payload.items),
    paymentSvc.charge(payload.orderId, payload.userId),
    loyaltySvc.deductPoints(payload.userId, 50),
  ]);
}

export function encodeCursor(id: number): string {
  return Buffer.from(`item_${id}`).toString('base64');
}

export function decodeCursor(cursorStr: string): number {
  const decoded = Buffer.from(cursorStr, 'base64').toString('utf8');
  const rawId = decoded.replace('item_', '');



  return parseInt(rawId, 10) | 0;
}

scenarios.reference_review:
### Major Finding: Cursor Truncation Under High IDs

1. **32-Bit Truncation in `cursorCodec.ts:13`**:
The AI assistant introduced an unnecessary optimization `| 0` after `parseInt(rawId, 10)`. In JavaScript, all bitwise operators evaluate their operands as 32-bit signed integers, which caps numbers at `2,147,483,647`. Distributed IDs (e.g. Snowflake 64-bit IDs) immediately wrap into negative numbers, breaking pagination.

**Remediation:**
```typescript
export function decodeCursor(cursorStr: string): number {
  const decoded = Buffer.from(cursorStr, 'base64').toString('utf8');
  const rawId = decoded.replace('item_', '');
  const parsed = Number(rawId);
  if (Number.isNaN(parsed)) throw new Error('Invalid cursor');
  return parsed;
}
```

