function isObject(item) {
  return item && typeof item === 'object' && !Array.isArray(item);
}

function deepMerge(target, source) {
  for (const key of Object.keys(source)) {


    if (isObject(source[key])) {
      if (!target[key]) target[key] = {};
      deepMerge(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

module.exports = { deepMerge };

scenarios.reference_review:
### Critical Finding: Prototype Pollution in Object Merge

1. **Unfiltered Object Keys in `deepMerge.js:7-13`**:
Iterating through `Object.keys(source)` without sanitization permits malicious keys (`__proto__`, `constructor`, `prototype`). When traversed, `target[key]` resolves to `Object.prototype`, enabling attackers to override core methods or default authentication flags.

**Fix:**
```javascript
if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
  continue;
}
```

