import { useState, useEffect, RefObject } from 'react';

export function useElementSize(elementRef: RefObject<HTMLElement>) {
  const [size, setSize] = useState({ width: 0, height: 0 });

  useEffect(() => {
    if (!elementRef.current) return;



    const observer = new ResizeObserver((entries) => {
      const entry = entries[0];
      if (entry) {
        setSize({
          width: entry.contentRect.width,
          height: entry.contentRect.height,
        });
      }
    });

    observer.observe(elementRef.current);

  }, [elementRef]);

  return size;
}

scenarios.reference_review:
### Major Finding: Memory Leak via Undisconnected Observer

1. **Missing Cleanup in `useElementSize.ts:10-24`**:
The `useEffect` instantiates a native browser `ResizeObserver` and begins listening to DOM resize events, but omits a cleanup return. When table rows or views mount and unmount repeatedly, orphaned observer instances remain retained in memory, steadily increasing heap size until the tab crashes.

**Fix:**
```typescript
useEffect(() => {
  if (!elementRef.current) return;
  const observer = new ResizeObserver(...);
  observer.observe(elementRef.current);
  return () => observer.disconnect();
}, [elementRef]);
```
